Before launch I run four gates, and any failure stops the launch. First, `git log` and `git status` confirm that `spe/predictions/r04.yaml` and `spe/plans/r04.md` are committed and unchanged since the `SPE r04 predict` commit. Second, I run the grader selftest. `grade.py` must score an oracle file built from `spe/evals/tasks/answers.json` at 1.0 on both category and priority. It must score an empty results file and a deliberately wrong file at 0, and it must not crash on either. I also run `judge.md` on a few round 3 replies whose tone verdicts are known, and I check that it agrees with them. Third, I regrade round 3's saved trial labels with this round's `grade.py` as a control. The numbers must match round 3's recorded results. Any change there is a grader change, and I log it in `spe/failures.md` before launch. Fourth, I dry run `spe/evals/harness/r04-workflow.js` with `args.only: ['B:T001', 'C2:T001', 'C2:T027']` and `args.trials: 1`. Every phase must return valid output with zero voids, and the run tells me the transcript directory to pass as `args.transcriptDir`. I then multiply the measured cost per trial by 310, which is 250 base trials plus the 60-trial top-up cap. I launch only if that total fits under $34, which is the $40 cap minus the $6 judge reserve. Once all four gates pass, I commit the script as `SPE r04 evaluate (harness)` and launch the full run.

The plan did not name a few things, so I put them in `args` with defaults marked "assumed": the runner command, the tickets file, the grader's CLI flags, and the ticket ID format. Change them there if round 3 used something else.

```js
export const meta = {
  name: 'spe-ticket-triage-eval',
  description: 'SPE eval for ticket triage. Runs each config on every ticket, grades labels with the code grader, judges reply tone with Opus, tops up split cells, then runs failure analysis and a completeness critic. The round number comes from args.round.',
  phases: [
    { title: 'Load' },
    { title: 'Trials' },
    { title: 'Peek scan' },
    { title: 'Grade' },
    { title: 'Judge' },
    { title: 'Top-up' },
    { title: 'Synthesis' },
  ],
};

// The round is set here and nowhere else. Paths and prompt text derive from it.
const ROUND = Number(args.round ?? 4);
const TAG = `r${String(ROUND).padStart(2, '0')}`;
const TMP = `/tmp/spe-${TAG}`;

// Defaults marked "assumed" are interfaces the plan did not name. Override them in args.
const A = {
  configs: args.configs ?? ['B', 'C2'],
  configNotes: args.configNotes ?? {
    B: '12-line prompt, 6 tools',
    C2: '12-line prompt, 3 tools plus a separate check_status tool',
  },
  tickets: args.tickets ?? 50,
  trials: args.trials ?? 5,
  ticketsPath: args.ticketsPath ?? 'spe/evals/tasks/tickets.jsonl',     // assumed
  runner: args.runner ?? 'node harness/run-ticket.mjs',               // assumed, lives outside spe/
  graderCmd: args.graderCmd ?? 'python3 spe/evals/graders/grade.py',  // flags below assumed
  answersPath: 'spe/evals/tasks/answers.json',
  judgeRubric: 'spe/evals/graders/judge.md',
  transcriptDir: args.transcriptDir ?? null,
  spendCapUsd: args.spendCapUsd ?? 40,
  reserveUsd: args.reserveUsd ?? 6,          // held back for judge batches (estimate)
  estTrialUsd: args.estTrialUsd ?? 0.08,     // first guess until real costs arrive (estimate)
  judgeBatch: args.judgeBatch ?? 10,
  judgeBatchUsd: args.judgeBatchUsd ?? 0.15, // estimate
  wave: args.wave ?? 25,
  topUpPerCell: args.topUpPerCell ?? 5,
  topUpTotal: args.topUpTotal ?? 60,
  maxVoids: args.maxVoids ?? 3,
  only: args.only ?? null,                   // dry run, e.g. ['B:T001', 'C2:T027']
  model: args.model ?? 'opus',
};

if (!A.only && !A.transcriptDir) {
  throw new Error('A full run needs args.transcriptDir for the peek scan. Take it from the dry run.');
}

// Trials must never touch these. The scan checks tool inputs against them.
const PEEK = ['spe/evals/', 'spe/predictions/', 'spe/plans/', 'spe/prediction-log', 'answers.json', 'grade.py', 'judge.md'];

// ---------- helpers ----------
const chunk = (xs, n) => { const out = []; for (let i = 0; i < xs.length; i += n) out.push(xs.slice(i, i + n)); return out; };
const rate = (xs, f) => (xs.length ? +(xs.filter(f).length / xs.length).toFixed(3) : null);
const mean = (xs, f) => { const v = xs.map(f).filter((x) => typeof x === 'number'); return v.length ? +(v.reduce((s, x) => s + x, 0) / v.length).toFixed(2) : null; };
const sum = (xs, f) => +xs.reduce((s, x) => s + (f(x) || 0), 0).toFixed(4);
function rng(seed) {
  let a = seed >>> 0;
  return () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}
function shuffle(xs, seed) {
  const r = rng(seed); const a = xs.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); const t = a[i]; a[i] = a[j]; a[j] = t; }
  return a;
}

// ---------- schemas ----------
const LOAD_SCHEMA = {
  type: 'object',
  required: ['prediction_committed', 'prediction_commit', 'grader_commit', 'judge_commit', 'tickets'],
  properties: {
    prediction_committed: { type: 'boolean' },
    prediction_commit: { type: 'string' },
    grader_commit: { type: 'string' },
    judge_commit: { type: 'string' },
    tickets: { type: 'array', items: { type: 'object', required: ['id', 'text'], properties: { id: { type: 'string' }, text: { type: 'string' } } } },
  },
};
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['harness_error', 'commands_run'],
  properties: {
    harness_error: { type: ['string', 'null'] },
    commands_run: { type: 'array', items: { type: 'string' } },
    label: { type: 'object', properties: { category: { type: ['string', 'null'] }, priority: { type: ['string', 'null'] } } },
    reply: { type: 'string' },
    tool_calls: { type: 'integer' },
    tool_errors: { type: 'integer' },
    tools_used: { type: 'array', items: { type: 'string' } },
    tool_inputs: { type: 'array', items: { type: 'string' } },
    input_tokens: { type: 'integer' },
    output_tokens: { type: 'integer' },
    runtime_ms: { type: 'integer' },
    cost_usd: { type: 'number' },
  },
};
const SCAN_SCHEMA = {
  type: 'object',
  required: ['flagged', 'not_found'],
  properties: {
    flagged: { type: 'array', items: { type: 'object', required: ['trial_id', 'evidence'], properties: { trial_id: { type: 'string' }, evidence: { type: 'string' } } } },
    not_found: { type: 'array', items: { type: 'string' } },
  },
};
const GRADE_SCHEMA = {
  type: 'object',
  required: ['grader_error', 'rows'],
  properties: {
    grader_error: { type: ['string', 'null'] },
    rows: { type: 'array', items: { type: 'object', required: ['trial_id', 'category_ok', 'priority_ok'], properties: { trial_id: { type: 'string' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' } } } },
  },
};
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['items'],
  properties: {
    items: { type: 'array', items: { type: 'object', required: ['id', 'pass', 'score', 'reason'], properties: { id: { type: 'string' }, pass: { type: 'boolean' }, score: { type: 'number' }, reason: { type: 'string' } } } },
  },
};
const ANALYSIS_SCHEMA = {
  type: 'object',
  required: ['failure_types', 'config_difference', 'suspected_grader_bugs'],
  properties: {
    failure_types: { type: 'array', items: { type: 'object', required: ['f_id', 'name', 'kind', 'what', 'how_to_spot', 'trial_ids', 'count_by_config', 'fix'], properties: {
      f_id: { type: 'string' }, name: { type: 'string' }, kind: { type: 'string' }, what: { type: 'string' }, how_to_spot: { type: 'string' },
      trial_ids: { type: 'array', items: { type: 'string' } }, count_by_config: { type: 'object' }, fix: { type: 'string' } } } },
    config_difference: { type: 'string' },
    suspected_grader_bugs: { type: 'array', items: { type: 'string' } },
  },
};
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'safe_to_compare', 'gaps', 'notes'],
  properties: { complete: { type: 'boolean' }, safe_to_compare: { type: 'boolean' }, gaps: { type: 'array', items: { type: 'string' } }, notes: { type: 'string' } },
};

// ---------- Load ----------
phase('Load');
const load = await agent(
`You prepare inputs for an evaluation run. Do not edit, stage, or commit any file.
1. Run: git log -1 --format=%H -- spe/predictions/${TAG}.yaml
   Run: git status --porcelain -- spe/predictions/${TAG}.yaml spe/plans/${TAG}.md
   Set prediction_committed to true only if the log prints a hash and the status prints nothing. Return the hash as prediction_commit. Do not open the prediction file.
2. Run git log -1 --format=%H for spe/evals/graders/grade.py and for ${A.judgeRubric}. Return them as grader_commit and judge_commit.
3. Read ${A.ticketsPath}. Return every ticket with its id and its full customer-facing text copied exactly. Leave out any field that holds a category, priority, label, or expected answer. Do not open ${A.answersPath}.`,
  { label: 'load inputs', phase: 'Load', schema: LOAD_SCHEMA, model: A.model });

if (!load.prediction_committed) throw new Error(`spe/predictions/${TAG}.yaml is missing, uncommitted, or edited. Halt before any trial.`);
if (load.tickets.length !== A.tickets) throw new Error(`Expected ${A.tickets} tickets, loaded ${load.tickets.length}. Halt.`);
const ticketText = Object.fromEntries(load.tickets.map((t) => [t.id, t.text]));

let cells = [];
for (const config of A.configs) for (const t of load.tickets) cells.push({ id: `${config}:${t.id}`, config, ticket: t });
if (A.only) cells = cells.filter((c) => A.only.includes(c.id));
log(`SPE ${TAG}: ${cells.length} cells x ${A.trials} trials. Cap $${A.spendCapUsd}, judge reserve $${A.reserveUsd}. Dry run: ${!!A.only}.`);

// ---------- budget ----------
const budget = { trialSpent: 0, trialCount: 0, committed: 0, judgeEst: 0, skipped: [], halted: null };
const estTrial = () => (budget.trialCount ? budget.trialSpent / budget.trialCount : A.estTrialUsd);
const skip = (what, why) => { budget.skipped.push({ what, why }); log(`SKIP ${what}: ${why}`); };

// ---------- trials ----------
function trialPrompt(cell, k, trialId) {
  const safe = trialId.replace(/[^A-Za-z0-9_-]/g, '_');
  return `TRIAL-ID: ${trialId}
You are the test driver for one evaluation trial. You are not the agent under test. Do not try to solve, check, or improve the ticket result.

You may do only these things:
1. Create ${TMP}/ and write the ticket JSON below to ${TMP}/${safe}.ticket.json.
2. Run this one command from the repository root:
   ${A.runner} --config ${cell.config} --ticket-file ${TMP}/${safe}.ticket.json --seed ${k} --out ${TMP}/${safe}.out.json
3. Read ${TMP}/${safe}.out.json and copy its fields into your result unchanged.

Do not open, list, search, or print anything under spe/. Do not read the runner's source code.
If the command fails or reports a rate limit, run it once more. If it fails again, put the error text in harness_error and leave the other fields out. Otherwise set harness_error to null.
List every shell command you ran, exactly as typed, in commands_run.

Ticket JSON:
${JSON.stringify({ id: cell.ticket.id, text: cell.ticket.text })}`;
}

async function runOne(cell, k, kind) {
  const trialId = `${cell.id}#${k}`;
  const rec = { trialId, cellId: cell.id, config: cell.config, ticketId: cell.ticket.id, k, kind, status: 'pending' };
  try {
    const r = await agent(trialPrompt(cell, k, trialId), {
      label: `trial ${trialId}`, phase: kind === 'base' ? 'Trials' : 'Top-up', schema: TRIAL_SCHEMA, model: A.model,
    });
    Object.assign(rec, r);
    // A missing label from the system under test is a model failure. The grader scores it wrong.
    rec.status = r.harness_error ? 'harness_error' : 'completed';
  } catch (e) {
    rec.status = 'harness_error';
    rec.harness_error = String((e && e.message) || e);
  }
  if (typeof rec.cost_usd !== 'number' && rec.status === 'completed') { rec.cost_usd = A.estTrialUsd; rec.cost_estimated = true; }
  // First peek check, in code: the driver's commands and the agent-under-test's tool inputs.
  const inputs = [...(rec.commands_run || []), ...(rec.tool_inputs || [])];
  const hit = inputs.find((s) => PEEK.some((p) => s.includes(p)));
  if (hit && rec.status === 'completed') { rec.status = 'void'; rec.void_reason = `tool input: ${hit}`; }
  return rec;
}

// Jobs are ordered trial index first, so a cap hit leaves both configs balanced.
async function runWaves(jobs, kind) {
  const out = [];
  const limit = A.spendCapUsd - A.reserveUsd;
  for (const group of chunk(jobs, A.wave)) {
    const wave = [];
    for (const j of group) {
      const est = estTrial();
      if (budget.halted) { skip(`${j.cell.id}#${j.k}`, budget.halted); continue; }
      if (budget.trialSpent + budget.committed + est > limit) {
        skip(`${j.cell.id}#${j.k}`, `would cross trial budget: spent $${budget.trialSpent.toFixed(2)}, est $${est.toFixed(3)}, limit $${limit}`);
        continue;
      }
      budget.committed += est;
      wave.push(j);
    }
    const res = await parallel(wave.map((j) => () => runOne(j.cell, j.k, kind)));
    budget.committed = 0;
    for (const r of res) {
      if (r.status === 'harness_error') continue;
      budget.trialSpent += r.cost_usd || 0;
      budget.trialCount += 1;
    }
    out.push(...res);
    log(`${kind} wave: ${res.length} run, ${res.filter((r) => r.status === 'harness_error').length} harness errors, trial spend $${budget.trialSpent.toFixed(2)} of $${limit}`);
    if (!budget.halted && budget.trialSpent >= limit) { budget.halted = 'trial budget reached'; log('HALT: trial budget reached. Remaining trials are skipped.'); }
  }
  return out;
}

phase('Trials');
const baseJobs = [];
for (let k = 1; k <= A.trials; k++) for (const cell of cells) baseJobs.push({ cell, k });
const base = await runWaves(baseJobs, 'base');

// ---------- Peek scan ----------
async function transcriptScan(recs) {
  const ids = recs.filter((r) => r.status === 'completed').map((r) => r.trialId);
  if (!ids.length) return;
  if (!A.transcriptDir) { log('Peek scan: no transcriptDir in this dry run. Only the in-code check ran.'); return; }
  const results = await parallel(chunk(ids, 50).map((batch, i) => () => agent(
`You audit evaluation transcripts. Do not edit anything.
Transcripts are under ${A.transcriptDir}. Each trial's transcript begins with a user message that starts "TRIAL-ID: <id>". Find the transcript for each id below.
In each transcript, look only at the inputs of tool calls the agent made, such as Read, Glob, Grep, and Bash. Ignore the prompt text itself.
Flag the trial if any tool input touches a path containing any of: ${PEEK.join(', ')}.
Return each flagged id with the exact tool input as evidence. Return each id whose transcript you could not find in not_found.
Ids:
${batch.join('\n')}`,
    { label: `peek scan ${i + 1}`, phase: 'Peek scan', schema: SCAN_SCHEMA, model: A.model })));
  const byId = Object.fromEntries(recs.map((r) => [r.trialId, r]));
  for (const res of results) {
    for (const f of res.flagged) if (byId[f.trial_id]) { byId[f.trial_id].status = 'void'; byId[f.trial_id].void_reason = `transcript: ${f.evidence}`; }
    for (const id of res.not_found) if (byId[id]) byId[id].scan_missing = true;
  }
}
function checkVoids(recs) {
  const voids = recs.filter((r) => r.status === 'void');
  const limit = A.only ? 0 : A.maxVoids;
  if (voids.length > limit) {
    throw new Error(`HALT: ${voids.length} trials read graders, answers, or predictions (${voids.map((v) => v.trialId).join(', ')}). Treat the answer key as leaked. Raw outputs are in ${TMP}.`);
  }
  if (voids.length) log(`Voided ${voids.length} trials that peeked: ${voids.map((v) => v.trialId).join(', ')}`);
}

phase('Peek scan');
await transcriptScan(base);
checkVoids(base);

// ---------- Grade (code first) ----------
async function grade(recs) {
  const todo = recs.filter((r) => r.status === 'completed');
  const byId = Object.fromEntries(todo.map((r) => [r.trialId, r]));
  const results = await parallel(chunk(todo, 50).map((batch, i) => () => agent(
`You run the code grader. Do not edit the grader, the answers file, or the rows. Do not grade any row yourself.
1. Write these rows to ${TMP}/grade-${TAG}-${batch[0].kind}-${i + 1}.jsonl, one JSON object per line.
2. Run: ${A.graderCmd} --answers ${A.answersPath} --results ${TMP}/grade-${TAG}-${batch[0].kind}-${i + 1}.jsonl --json
3. Return one entry per row with trial_id, category_ok, and priority_ok copied from the grader output. If the grader crashes or drops a row, put the error in grader_error. Otherwise set grader_error to null.
Rows:
${batch.map((r) => JSON.stringify({ trial_id: r.trialId, ticket_id: r.ticketId, label: { category: r.label?.category ?? null, priority: r.label?.priority ?? null } })).join('\n')}`,
    { label: `grade ${i + 1}`, phase: 'Grade', schema: GRADE_SCHEMA, model: A.model })));
  for (const res of results) {
    if (res.grader_error) throw new Error(`HALT: grader failed: ${res.grader_error}. Raw outputs are in ${TMP}.`);
    for (const row of res.rows) {
      const r = byId[row.trial_id];
      if (!r) continue;
      r.graded = true;
      r.category_ok = row.category_ok;
      r.priority_ok = row.priority_ok;
      r.both_ok = row.category_ok && row.priority_ok;
    }
  }
  const missing = todo.filter((r) => !r.graded);
  if (missing.length) throw new Error(`HALT: grader returned no row for ${missing.map((r) => r.trialId).join(', ')}.`);
}

phase('Grade');
await grade(base);

// ---------- Judge (only what code cannot check) ----------
phase('Judge');
log('Tone judge is Opus. No judge from a different model family is available, so tone scores share Claude blind spots if the configs run on Claude.');
const toJudge = shuffle(base.filter((r) => r.status === 'completed' && r.reply), ROUND * 7919)
  .map((r, i) => ({ rec: r, jid: `J${String(i + 1).padStart(3, '0')}` }));
const judgeBatches = [];
for (const b of chunk(toJudge, A.judgeBatch)) {
  if (budget.trialSpent + budget.judgeEst + A.judgeBatchUsd > A.spendCapUsd) {
    skip(`judge batch ${b[0].jid}-${b[b.length - 1].jid}`, 'would cross the total spend cap');
    continue;
  }
  budget.judgeEst += A.judgeBatchUsd;
  judgeBatches.push(b);
}
const judged = await parallel(judgeBatches.map((b, i) => () => agent(
`You judge reply tone. Read ${A.judgeRubric} and apply it exactly. Do not open any other file under spe/.
Score only tone as the rubric defines it. Do not judge whether the category or priority is right. You do not know which system wrote each reply, and you must not try to find out.
For each item return id, pass (true or false per the rubric), score on the rubric's scale, and a one-line reason that quotes the reply.
Items:
${JSON.stringify(b.map((x) => ({ id: x.jid, ticket: ticketText[x.rec.ticketId], reply: x.rec.reply })))}`,
  { label: `judge ${i + 1}`, phase: 'Judge', schema: JUDGE_SCHEMA, model: 'opus' })));
const byJid = Object.fromEntries(toJudge.map((x) => [x.jid, x.rec]));
for (const res of judged) for (const it of res.items) if (byJid[it.id]) byJid[it.id].tone = { pass: it.pass, score: it.score, reason: it.reason };

// ---------- Top-up split cells ----------
// Top-up trials get code grading only. Headline numbers use base trials, which match the prediction.
phase('Top-up');
const cellStats = {};
for (const r of base.filter((x) => x.graded)) {
  const s = (cellStats[r.cellId] ||= { pass: 0, n: 0 });
  s.n += 1;
  if (r.both_ok) s.pass += 1;
}
const splitCells = cells
  .filter((c) => cellStats[c.id] && cellStats[c.id].pass > 0 && cellStats[c.id].pass < cellStats[c.id].n)
  .sort((a, b) => Math.abs(cellStats[a.id].pass / cellStats[a.id].n - 0.5) - Math.abs(cellStats[b.id].pass / cellStats[b.id].n - 0.5));
const topJobs = [];
for (let e = 1; e <= A.topUpPerCell; e++) for (const cell of splitCells) if (topJobs.length < A.topUpTotal) topJobs.push({ cell, k: A.trials + e });
log(`Top-up: ${splitCells.length} split cells, ${topJobs.length} extra trials queued (cap ${A.topUpPerCell} per cell, ${A.topUpTotal} total).`);
const topup = await runWaves(topJobs, 'topup');
await transcriptScan(topup);
checkVoids([...base, ...topup]);
await grade(topup);

// ---------- Metrics ----------
function summarize(recs, config) {
  const all = recs.filter((r) => r.config === config);
  const done = all.filter((r) => r.status === 'completed' && r.graded);
  const toned = done.filter((r) => r.tone);
  return {
    config,
    note: A.configNotes[config],
    completed: done.length,
    harness_errors: all.filter((r) => r.status === 'harness_error').length,
    voided: all.filter((r) => r.status === 'void').length,
    category_acc: rate(done, (r) => r.category_ok),
    priority_acc: rate(done, (r) => r.priority_ok),
    both_acc: rate(done, (r) => r.both_ok),
    judged: toned.length,
    tone_pass: rate(toned, (r) => r.tone.pass),
    tone_score_mean: mean(toned, (r) => r.tone.score),
    runtime_ms_mean: mean(done, (r) => r.runtime_ms),
    tool_calls_mean: mean(done, (r) => r.tool_calls),
    tokens_mean: mean(done, (r) => (r.input_tokens || 0) + (r.output_tokens || 0)),
    tool_errors_mean: mean(done, (r) => r.tool_errors),
    trials_with_tool_error: rate(done, (r) => (r.tool_errors || 0) > 0),
    check_status_use: rate(done, (r) => (r.tools_used || []).includes('check_status')),
    cost_usd: sum(done, (r) => r.cost_usd),
    cost_estimated_trials: done.filter((r) => r.cost_estimated).length,
  };
}
const headline = A.configs.map((c) => summarize(base, c));
const splitTable = splitCells.map((c) => {
  const extra = topup.filter((r) => r.cellId === c.id && r.graded);
  const s = cellStats[c.id];
  return { cell: c.id, base: `${s.pass}/${s.n}`, with_topup: `${s.pass + extra.filter((r) => r.both_ok).length}/${s.n + extra.length}` };
});
const allRecs = [...base, ...topup];
const counts = {
  expected_base: cells.length * A.trials,
  base_completed_graded: base.filter((r) => r.graded).length,
  base_void: base.filter((r) => r.status === 'void').length,
  base_harness_error: base.filter((r) => r.status === 'harness_error').length,
  skipped: budget.skipped,
  judge_expected: toJudge.length,
  judge_returned: toJudge.filter((x) => x.rec.tone).length,
  scan_missing: allRecs.filter((r) => r.scan_missing).map((r) => r.trialId),
  topup_run: topup.length,
  trial_spend_usd: +budget.trialSpent.toFixed(2),
  judge_spend_est_usd: +budget.judgeEst.toFixed(2),
  cap_usd: A.spendCapUsd,
  halted: budget.halted,
};
log(`Headline: ${JSON.stringify(headline.map((h) => ({ c: h.config, both: h.both_acc, tone: h.tone_pass, n: h.completed })))}`);

// ---------- Synthesis ----------
phase('Synthesis');
const failed = allRecs
  .filter((r) => r.graded && (!r.both_ok || (r.tone && !r.tone.pass)))
  .map((r) => ({
    trial_id: r.trialId, config: r.config, kind: r.kind, ticket_id: r.ticketId,
    ticket: (ticketText[r.ticketId] || '').slice(0, 600),
    label: r.label ?? null, category_ok: r.category_ok, priority_ok: r.priority_ok,
    tone: r.tone ?? null, tools_used: r.tools_used ?? [], tool_errors: r.tool_errors ?? 0,
  }));

const [analysis, critic] = await parallel([
  () => agent(
`You analyze failures from an evaluation run. Do not edit any file.
You may read ${A.answersPath} for the gold labels and spe/failures.md for existing failure types.
Configs: ${A.configs.map((c) => `${c} is ${A.configNotes[c]}`).join('. ')}. The configs differ only in the tool split.
Headline metrics (base trials): ${JSON.stringify(headline)}
Split cells: ${JSON.stringify(splitTable)}
Failed trials: ${JSON.stringify(failed)}
Group the failures into types. Reuse an existing F-number when a type matches. Use "NEW" as f_id for new types.
For each type give name, kind (agent, grader, harness, or task), what happened, how to spot it, trial ids, count per config, and a fix.
In config_difference, say which B versus C2 differences come from the tool split and which do not.
List any failure that looks like a grader or answer-key bug in suspected_grader_bugs.`,
    { label: 'failure analysis', phase: 'Synthesis', schema: ANALYSIS_SCHEMA, model: A.model }),
  () => agent(
`You check whether an evaluation run is complete. Do not edit any file.
Expected base trials: ${cells.length} cells x ${A.trials} trials = ${cells.length * A.trials}.
Counts: ${JSON.stringify(counts)}
Headline: ${JSON.stringify(headline)}
Check that every expected base trial is completed and graded, voided, a harness error, or a logged skip. Check that every completed base trial with a reply has a tone judgment or a logged skip. Check that the peek scan found every completed trial. Check that spend stayed under the cap and top-up stayed within its caps.
List each gap. Set safe_to_compare to false if gaps would bias a comparison against the saved prediction.`,
    { label: 'completeness critic', phase: 'Synthesis', schema: CRITIC_SCHEMA, model: A.model }),
]);

return {
  round: ROUND,
  tag: TAG,
  dry_run: !!A.only,
  prediction_commit: load.prediction_commit,
  grader_commit: load.grader_commit,
  judge_commit: load.judge_commit,
  headline,
  split_cells: splitTable,
  counts,
  failure_analysis: analysis,
  critic,
  trials: allRecs,
};
